const items = $input.all();
const first = items[0] ? items[0].json : {};

// ---- Branch A: triggered by the demo page (has a .body) ----
if (first.body !== undefined) {
  const body = first.body || {};
  const apiKey = body.api_key || '';
  const topic = body.topic || 'Clay';
  const context = body.context || "the B2B data enrichment / outbound automation platform for sales teams — not the other Clay app, the personal relationship-manager for remembering friends' birthdays and staying in touch";
  let mentions = body.mentions;
  if (!Array.isArray(mentions) || mentions.length === 0) {
    mentions = [
      "Just started using Clay to keep up with friends' birthdays and life updates — way better than my notes app.",
      "Our outbound team plugged Clay into the CRM and cut list-building time in half.",
      "Clay just shipped a new integration with LinkedIn for personal contact syncing.",
      "We're scaling our GTM engine using Clay's enrichment waterfalls across five data providers.",
      "Clay raised a new round to grow their relationship intelligence platform for professionals.",
      "Finally automated our lead lists with Clay — no more manual scraping."
    ];
  }
  return mentions.map(text => ({ json: { text, link: '', api_key: apiKey, topic, context } }));
}

// ---- Branch B: triggered by the schedule + RSS feed ----
// EDIT these three lines for your own product before you rely on this branch:
const TOPIC = 'Clay';
const CONTEXT = "the B2B data enrichment / outbound automation platform for sales teams — not the other Clay app, the personal relationship-manager for remembering friends' birthdays and staying in touch";
const API_KEY = 'PASTE_YOUR_JEV_API_KEY_HERE'; // this branch runs unattended, so it needs a real stored key

return items.map(item => ({
  json: {
    text: (item.json.title || '') + '. ' + (item.json.contentSnippet || item.json.content || ''),
    link: item.json.link || '',
    api_key: API_KEY,
    topic: TOPIC,
    context: CONTEXT
  }
}));

