function extractProb(v){
  if (v == null) return null;
  if (typeof v === 'number') return v;
  if (typeof v === 'object'){
    if (typeof v.noul === 'number') return v.noul;
    if (typeof v.score === 'number') return v.score;
    if (typeof v.confidence === 'number') return v.confidence;
    if (typeof v.probability === 'number') return v.probability;
  }
  return null;
}

return $input.all().map((item, i) => {
  const data = item.json;
  const container = data.answers || data.questions || data.results || data;
  const prob = extractProb(container ? container.real_mention : null);
  const original = $('Prepare Items').all()[i].json;
  return {
    json: {
      text: original.text,
      link: original.link,
      prob: prob === null ? 0 : prob
    }
  };
});
